// Cloud sync: generates src/lib/sync/model.generated.ts (each synced table's key and field types, which the sync codec
// needs to move a row between PostgreSQL, the wire and SQLite) from prisma/schema.prisma and src/lib/sync/entities.ts.
//   npx tsx scripts/sync-schema.ts                 write model.generated.ts
//   npx tsx scripts/sync-schema.ts --triggers pg   print the PostgreSQL change-capture triggers (for a migration)
//   npx tsx scripts/sync-schema.ts --triggers sqlite
// src/lib/sync/sync-schema.test.ts fails when the generated file is out of date or a synced table has no triggers.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { SYNC_ENTITIES } from "../src/lib/sync/entities";
import { parseSchema, type ModelMeta } from "../src/lib/sync/meta";
import { pgTrigger, sqliteTriggers } from "../src/lib/sync/triggers";

const ROOT = new URL("../", import.meta.url);
const SCHEMA = fileURLToPath(new URL("prisma/schema.prisma", ROOT));
const OUT = fileURLToPath(new URL("src/lib/sync/model.generated.ts", ROOT));

export function renderModel(models: Record<string, ModelMeta>): string {
  const synced: Record<string, ModelMeta> = {};
  for (const e of SYNC_ENTITIES) {
    const m = models[e.name];
    if (!m) throw new Error(`Synced entity ${e.name} is not a model in prisma/schema.prisma`);
    if (!m.pk.length) throw new Error(`Synced entity ${e.name} has no key`);
    synced[e.name] = m;
  }
  const lines = Object.entries(synced).map(([name, m]) => `  ${name}: ${JSON.stringify(m)},`);
  return `// GENERATED by scripts/sync-schema.ts from prisma/schema.prisma: do not edit. Each synced table's key and field types.
import type { ModelMeta } from "./meta";

export const SYNC_MODEL: Record<string, ModelMeta> = {
${lines.join("\n")}
};
`;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const models = parseSchema(readFileSync(SCHEMA, "utf8"));
  const i = process.argv.indexOf("--triggers");
  if (i > 0) {
    const dialect = process.argv[i + 1];
    for (const e of SYNC_ENTITIES) {
      const m = models[e.name]!;
      console.log(dialect === "pg" ? pgTrigger(e, m.pk) : sqliteTriggers(e, m.pk, Object.keys(m.fields)));
      console.log("");
    }
  } else {
    writeFileSync(OUT, renderModel(models));
    console.log(`wrote ${OUT}`);
  }
}
